using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Http;
namespace Kohami.Core;
/// <summary>The explicitly used JSON Schema subset; unsupported assertions fail closed at load.</summary>
public sealed class RuntimeContract {
 private readonly JsonDocument document;
 private readonly List<(string Method,Regex Path,JsonElement Operation)> routes=[];
 public RuntimeContract(string file){document=JsonDocument.Parse(File.ReadAllText(file));foreach(var schema in document.RootElement.GetProperty("components").GetProperty("schemas").EnumerateObject())CheckSchema(schema.Value);foreach(var p in document.RootElement.GetProperty("paths").EnumerateObject())foreach(var m in p.Value.EnumerateObject()){var operation=m.Value;if(operation.TryGetProperty("parameters",out var parameters))foreach(var parameterRef in parameters.EnumerateArray()){var parameter=Resolve(parameterRef);if(parameter.TryGetProperty("schema",out var parameterSchema))CheckSchema(Resolve(parameterSchema));}if(operation.TryGetProperty("requestBody",out var body))CheckContent(body);if(operation.TryGetProperty("responses",out var responses))foreach(var response in responses.EnumerateObject())CheckContent(response.Value);var pattern="^/api/v1"+Regex.Replace(p.Name,@"\{[^}]+\}","[^/]+")+"$";routes.Add((m.Name.ToUpperInvariant(),new Regex(pattern,RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(50)),operation));}}
 private void CheckContent(JsonElement responseOrBody){if(!responseOrBody.TryGetProperty("content",out var content))return;foreach(var media in content.EnumerateObject())if(media.Value.TryGetProperty("schema",out var schema))CheckSchema(Resolve(schema));}

 private static readonly HashSet<string> Supported = new(StringComparer.Ordinal) {"$ref","type","required","properties","additionalProperties","enum","const","anyOf","oneOf","allOf","if","then","else","not","items","minItems","maxItems","uniqueItems","minLength","maxLength","pattern","format","minimum","maximum","exclusiveMinimum","exclusiveMaximum","description","title","default","examples","example","deprecated","readOnly","writeOnly","nullable"};
 private static void CheckSchema(JsonElement s){if(s.ValueKind is JsonValueKind.True or JsonValueKind.False)return;if(s.ValueKind!=JsonValueKind.Object)throw new InvalidOperationException("CONTRACT_SCHEMA_INVALID");foreach(var p in s.EnumerateObject()){if(!Supported.Contains(p.Name)&&!p.Name.StartsWith("x-",StringComparison.Ordinal))throw new InvalidOperationException("CONTRACT_ASSERTION_UNSUPPORTED");if(p.Name=="format"&&p.Value.GetString() is not ("date-time" or "email" or "uuid" or "password" or "int32" or "int64" or "double" or "uri"))throw new InvalidOperationException("CONTRACT_FORMAT_UNSUPPORTED");if(p.Name=="properties")foreach(var child in p.Value.EnumerateObject())CheckSchema(child.Value);else if(p.Name is "anyOf" or "oneOf" or "allOf")foreach(var child in p.Value.EnumerateArray())CheckSchema(child);else if(p.Name is "items" or "additionalProperties" or "if" or "then" or "else" or "not")CheckSchema(p.Value);}}
 public JsonElement? Operation(HttpContext c)=>routes.FirstOrDefault(r=>r.Method==c.Request.Method&&r.Path.IsMatch(c.Request.Path.Value??"")).Operation.ValueKind==JsonValueKind.Undefined?null:routes.First(r=>r.Method==c.Request.Method&&r.Path.IsMatch(c.Request.Path.Value??"")).Operation;
 public JsonElement Resolve(JsonElement s){if(!s.TryGetProperty("$ref",out var r))return s;var target=document.RootElement;foreach(var part in r.GetString()![2..].Split('/'))target=target.GetProperty(part.Replace("~1","/").Replace("~0","~"));return Resolve(target);}
 public bool Valid(JsonElement input,JsonElement s){s=Resolve(s);if(s.ValueKind==JsonValueKind.True)return true;if(s.ValueKind==JsonValueKind.False)return false;
  if(s.TryGetProperty("allOf",out var all)&&!all.EnumerateArray().All(x=>Valid(input,x)))return false;
  if(s.TryGetProperty("anyOf",out var any)&&!any.EnumerateArray().Any(x=>Valid(input,x)))return false;
  if(s.TryGetProperty("oneOf",out var one)&&one.EnumerateArray().Count(x=>Valid(input,x))!=1)return false;
  if(s.TryGetProperty("not",out var not)&&Valid(input,not))return false;
  if(s.TryGetProperty("if",out var condition)){var branch=Valid(input,condition)?"then":"else";if(s.TryGetProperty(branch,out var selected)&&!Valid(input,selected))return false;}
  if(s.TryGetProperty("const",out var constant)&&!JsonElement.DeepEquals(input,constant))return false;
  if(s.TryGetProperty("enum",out var enumeration)&&!enumeration.EnumerateArray().Any(x=>JsonElement.DeepEquals(input,x)))return false;
  if(s.TryGetProperty("type",out var type)){bool Match(string t)=>t switch{"object"=>input.ValueKind==JsonValueKind.Object,"array"=>input.ValueKind==JsonValueKind.Array,"string"=>input.ValueKind==JsonValueKind.String,"integer"=>input.ValueKind==JsonValueKind.Number&&input.TryGetInt64(out _),"number"=>input.ValueKind==JsonValueKind.Number,"boolean"=>input.ValueKind is JsonValueKind.True or JsonValueKind.False,"null"=>input.ValueKind==JsonValueKind.Null,_=>false};if(!(type.ValueKind==JsonValueKind.Array?type.EnumerateArray().Any(t=>Match(t.GetString()!)):Match(type.GetString()!)))return false;}
  if(input.ValueKind==JsonValueKind.Object){var names=new HashSet<string>(StringComparer.Ordinal);foreach(var p in input.EnumerateObject())if(!names.Add(p.Name))return false;
   if(s.TryGetProperty("required",out var required)&&required.EnumerateArray().Any(r=>!input.TryGetProperty(r.GetString()!,out _)))return false;
   foreach(var p in input.EnumerateObject()){if(s.TryGetProperty("properties",out var properties)&&properties.TryGetProperty(p.Name,out var child)){if(!Valid(p.Value,child))return false;}else if(s.TryGetProperty("additionalProperties",out var extra)){if(extra.ValueKind==JsonValueKind.False)return false;if(extra.ValueKind==JsonValueKind.Object&&!Valid(p.Value,extra))return false;}}
  }
  if(input.ValueKind==JsonValueKind.Array){var values=input.EnumerateArray().ToArray();if(s.TryGetProperty("minItems",out var min)&&values.Length<min.GetInt32())return false;if(s.TryGetProperty("maxItems",out var max)&&values.Length>max.GetInt32())return false;if(s.TryGetProperty("uniqueItems",out var unique)&&unique.GetBoolean()){for(var i=0;i<values.Length;i++)for(var j=i+1;j<values.Length;j++)if(JsonElement.DeepEquals(values[i],values[j]))return false;}if(s.TryGetProperty("items",out var items)&&!values.All(v=>Valid(v,items)))return false;}
  if(input.ValueKind==JsonValueKind.String){var text=input.GetString()!;var length=text.EnumerateRunes().Count();if(s.TryGetProperty("minLength",out var min)&&length<min.GetInt32())return false;if(s.TryGetProperty("maxLength",out var max)&&length>max.GetInt32())return false;if(s.TryGetProperty("pattern",out var pattern)&&!Regex.IsMatch(text,pattern.GetString()!,RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(50)))return false;if(s.TryGetProperty("format",out var format)){if(format.GetString()=="date-time"&&!DateTimeOffset.TryParse(text,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out _))return false;if(format.GetString()=="uri"&&!Uri.TryCreate(text,UriKind.Absolute,out _))return false;if(format.GetString()=="uuid"&&!Guid.TryParseExact(text,"D",out _))return false;if(format.GetString()=="email"&&(!text.Contains('@')||text.Contains('\n')||text.Contains('\r')))return false;}}
  if(input.ValueKind==JsonValueKind.Number){if(!input.TryGetDecimal(out var value))return false;foreach(var k in new[]{"minimum","maximum","exclusiveMinimum","exclusiveMaximum"})if(s.TryGetProperty(k,out var n)){var bound=n.GetDecimal();if(k=="minimum"&&value<bound||k=="maximum"&&value>bound||k=="exclusiveMinimum"&&value<=bound||k=="exclusiveMaximum"&&value>=bound)return false;}}
  return true;
 }
 public bool ValidResponse(HttpContext c,JsonElement payload){var operation=Operation(c);if(operation is null||!operation.Value.TryGetProperty("responses",out var responses))return false;var key=c.Response.StatusCode.ToString(CultureInfo.InvariantCulture);if(!responses.TryGetProperty(key,out var response)&&!responses.TryGetProperty("default",out response))return false;if(!response.TryGetProperty("content",out var content))return false;var media=c.Response.ContentType?.Split(';')[0]??"";if(!content.TryGetProperty(media,out var representation)||!representation.TryGetProperty("schema",out var schema))return false;return Valid(payload,schema);}
 public async Task ValidateRequestAsync(HttpContext c){var operation=Operation(c)??throw new KohamiException(404,"RESOURCE_NOT_FOUND");
  if(operation.TryGetProperty("parameters",out var parameters))foreach(var declared in parameters.EnumerateArray()){var parameter=Resolve(declared);if(parameter.GetProperty("in").GetString()!="header")continue;var name=parameter.GetProperty("name").GetString()!;var value=c.Request.Headers[name].ToString();if(value.Length==0){if(parameter.TryGetProperty("required",out var required)&&required.GetBoolean())throw new KohamiException(name=="If-Match"||name=="Idempotency-Key"?428:422,name=="If-Match"||name=="Idempotency-Key"?"PRECONDITION_REQUIRED":"VALIDATION_ERROR");continue;}if(!Valid(JsonSerializer.SerializeToElement(value),Resolve(parameter.GetProperty("schema"))))throw new KohamiException(422,"VALIDATION_ERROR");}
  if(!operation.TryGetProperty("requestBody",out var body))return;
  if(c.Request.ContentLength>65536)throw new KohamiException(413,"PAYLOAD_TOO_LARGE");if(c.Request.ContentType?.Split(';')[0]!="application/json")throw new KohamiException(415,"UNSUPPORTED_MEDIA_TYPE");
  c.Request.EnableBuffering(65536,65536);try{using var input=await JsonDocument.ParseAsync(c.Request.Body,cancellationToken:c.RequestAborted);var schema=body.GetProperty("content").GetProperty("application/json").GetProperty("schema");if(!Valid(input.RootElement,schema))throw new KohamiException(422,"VALIDATION_ERROR");}catch(JsonException){throw new KohamiException(422,"VALIDATION_ERROR");}catch(IOException){throw new KohamiException(413,"PAYLOAD_TOO_LARGE");}finally{c.Request.Body.Position=0;}
 }
}
